const heading=(eyebrow,title,desc='')=>`<div class="modal-header"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div></div>`;
function welcome(){
 modal(heading('BREAKWATER · ONE COAST. ONE CITY.','The Harbor Charter','Alder Bay has five years to become a city. You have the land, a working town, and a commission.'),
 `<div class="intro-illustration"><div class="intro-metric"><small>GROW TO</small><strong>1,200</strong><span>residents</span></div><div class="intro-metric"><small>BUILD TRUST</small><strong>70%</strong><span>city approval</span></div><div class="intro-metric"><small>YOUR TERM</small><strong>5 years</strong><span>January 2032 – January 2037</span></div></div><div class="intro-text"><p>Shape the streets. Zone homes, shops, and workshops. Let the town grow around the roads and services you provide.</p><p>In month 30, a major storm will test the coast. Prepare the city, restore damaged sites, and hold all five charter goals for three months.</p></div><div class="intro-controls"><span><kbd>Drag</kbd> Build roads & zones</span><span><kbd>Space</kbd> Pause time</span><span><kbd>Wheel</kbd> Zoom</span></div>`,
 `${saved?'<button class="button-secondary" id="continue-save">Continue saved city</button>':''}<button class="button-primary" id="begin-game">Begin the charter</button>`,'welcome',false);
 $('begin-game').onclick=()=>{replaceCity(new City());started=true;tutorial=0;closeModal();setSpeed(0);renderTutorial();storeSave(true);if(audioOn)game.audio.music(song);};
 if($('continue-save'))$('continue-save').onclick=()=>{replaceCity(City.fromSave(saved.snapshot()));started=true;closeModal();setSpeed(0);if(audioOn)game.audio.music(song);if(city.pendingEvent)showEvent();else if(city.result&&!city.sandbox)resultModal();};
}
function renderTutorial(){
 const steps=[['Start with the street','The town has a working road grid. Select Homes, then drag over vacant land within three tiles of a road.','Select Homes','home'],['Keep services ahead of growth','Each new district uses water and power. The city advisor will warn you when the grid needs more capacity.','Select Utilities','utilities'],['Bring the plan to life','Use 1× to run the city. Zones will develop over time. You can pause, build, and inspect at any point.','Run the city','run'],['Prepare for the coast','Use Flood risk to find exposed land. The storm comes in month 30. Barriers and shelters reduce damage.','Show flood risk','risk']];
 const card=$('tutorial-card');if(tutorial<0||tutorial>=steps.length){tutorial=-1;card.classList.add('hidden');return;}const s=steps[tutorial];
 card.classList.remove('hidden');card.innerHTML=`<div class="step-label"><span>FIELD NOTES ${tutorial+1} / 4</span><button id="skip-tutorial" aria-label="Close tutorial">×</button></div><h2>${s[0]}</h2><p>${s[1]}</p><div class="tutorial-buttons"><button id="tutorial-action">${s[2]}</button><button id="next-tutorial" class="next">${tutorial===3?'Finish':'Next'}</button></div>`;
 $('skip-tutorial').onclick=()=>{tutorial=-1;card.classList.add('hidden');};$('next-tutorial').onclick=()=>{tutorial++;renderTutorial();};$('tutorial-action').onclick=()=>{if(s[3]==='utilities')palette('utilities');else if(s[3]==='run')setSpeed(1);else if(s[3]==='risk')setLayer('risk');else chooseTool(s[3]);};
}
function budgetModal(){
 modal(heading('CITY FINANCE','The monthly budget','New buildings have operating costs. Review the balance before you commit.'),
 `<div class="budget-summary"><div><small>Treasury</small><strong id="budget-funds"></strong></div><div><small>Monthly income</small><strong id="budget-income"></strong></div><div><small>Monthly balance</small><strong id="budget-net"></strong></div></div><table class="finance-table"><thead><tr><th>Operating cost</th><th>Each month</th></tr></thead><tbody id="budget-rows"></tbody></table><div class="budget-sliders"><div><label class="slider-head" for="tax-slider">City tax rate <output id="tax-value">${city.tax}%</output></label><input id="tax-slider" type="range" min="5" max="15" step="1" value="${city.tax}"><p class="slider-note">Higher tax raises income. It also lowers approval and demand. A 9% rate is neutral.</p></div><div><label class="slider-head" for="funding-slider">Service funding <output id="funding-value">${city.funding}%</output></label><input id="funding-slider" type="range" min="50" max="100" step="10" value="${city.funding}"><p class="slider-note">Lower funding reduces service range and public trust. Utilities retain their fixed operating costs.</p></div></div><div class="bond-row"><span><strong id="bond-title">${city.bonds} of 3 bonds issued</strong><small>Each $5,000 bond costs $50 per month.</small></span><div class="bond-buttons"><button class="button-secondary" id="repay-bond">Repay $5,000</button><button class="button-secondary" id="issue-bond">Issue $5,000</button></div></div><p class="modal-inline-error hidden" id="budget-error"></p>`,
 '<span class="note">Time stops while this window is open.</span><button class="button-primary" id="budget-done">Return to city</button>','budget');
 $('tax-slider').oninput=e=>{city.setTax(Number(e.target.value));undoStack=[];updateUI();};$('funding-slider').oninput=e=>{city.setFunding(Number(e.target.value));undoStack=[];updateUI();};
 const bond=repay=>{const v=city.bond(repay);if(!v.ok){$('budget-error').textContent=v.reason;$('budget-error').classList.remove('hidden');}else{undoStack=[];$('budget-error').classList.add('hidden');sfx('coin');updateUI();}};
 $('issue-bond').onclick=()=>bond(false);$('repay-bond').onclick=()=>bond(true);$('budget-done').onclick=closeModal;refreshBudget();
}
function refreshBudget(){if(!$('budget-funds'))return;const s=city.stats;$('budget-funds').textContent=money(city.funds);$('budget-income').textContent=money(s.income);$('budget-net').textContent=signed(s.net);$('budget-net').className=s.net>=0?'positive':'negative';$('tax-value').textContent=city.tax+'%';$('funding-value').textContent=city.funding+'%';$('budget-rows').innerHTML=[['Road network',s.roadsUpkeep],['Power and water',s.utilityUpkeep],['Services, parks, and barriers',s.serviceUpkeep],['City administration',s.admin],['Bond interest',s.debtService],['Total operating costs',s.upkeep]].map(([name,cost])=>`<tr><td>${name}</td><td>${money(cost)}</td></tr>`).join('');$('bond-title').textContent=city.bonds+' of 3 bonds issued';$('repay-bond').disabled=city.bonds===0||city.funds<5000;$('issue-bond').disabled=city.bonds>=3;}
function recordsModal(){
 const s=city.stats;modal(heading('CITY RECORDS','Alder Bay in numbers','These measures come from the current city simulation.'),
 `<div class="record-stats">${[['Employment',s.employment+'%'],['Health coverage',s.health+'%'],['School coverage',s.education+'%'],['Fire coverage',s.fireCoverage+'%'],['Flood readiness',s.resilience+'%'],['Pollution',s.pollution+' / 100']].map(([label,value])=>`<div><small>${label}</small><strong>${value}</strong></div>`).join('')}</div><div class="chart-title"><span>Population history</span><small>${city.history.length} monthly records</small></div><canvas id="population-chart" class="record-chart" width="680" height="160" aria-label="Population history chart"></canvas><div class="chart-title"><span>Utility capacity</span><small>Roads distribute both networks</small></div><table class="finance-table"><tbody><tr><td>Power demand / capacity</td><td>${s.powerDemand} / ${s.powerCapacity}</td></tr><tr><td>Water demand / capacity</td><td>${s.waterDemand} / ${s.waterCapacity}</td></tr><tr><td>Homes and businesses with power</td><td>${s.power}%</td></tr><tr><td>Homes and businesses with water</td><td>${s.water}%</td></tr><tr><td>Road access</td><td>${s.roadCoverage}%</td></tr></tbody></table>`,
 '<button class="button-primary" id="records-done">Return to city</button>','records');
 $('records-done').onclick=closeModal;const c=$('population-chart'),g=c.getContext('2d'),h=city.history,vals=h.map(v=>v.population),max=Math.max(1200,...vals),W=c.width,H=c.height;g.clearRect(0,0,W,H);g.strokeStyle='#819e7860';g.setLineDash([4,5]);g.beginPath();g.moveTo(0,H-15-1200/max*(H-35));g.lineTo(W,H-15-1200/max*(H-35));g.stroke();g.setLineDash([]);g.fillStyle='#adc294';g.font='12px sans-serif';g.fillText('Charter: 1,200',W-99,H-20-1200/max*(H-35));g.strokeStyle='#c8cf9d';g.lineWidth=2;g.beginPath();vals.forEach((v,i)=>{const x=10+i/(vals.length-1||1)*(W-20),y=H-15-v/max*(H-35);i?g.lineTo(x,y):g.moveTo(x,y);});g.stroke();if(vals.length===1){g.beginPath();g.arc(10,H-15-vals[0]/max*(H-35),3,0,Math.PI*2);g.fill();}
}
const GUIDE={
 basics:`<h3>Build a city that works</h3><p>You control land use and infrastructure. Residents and businesses develop the zones when their needs are met.</p><ul><li>Select Road, Homes, Shops, or Works. Drag across the map to preview the cost. Release to build.</li><li>Roads must connect to the regional road at tile 0, 14. A zone needs a connected road within 3 tiles.</li><li>Roads carry power and water. Build wind stations for power. Build water pumps within 3 tiles of the shore.</li><li>Each month takes 8 seconds at 1×. Use Space to pause. You can build and inspect while paused.</li></ul><h3>Complete the commission</h3><p>Before month 60, hold all five goals for three months: 1,200 residents, 70% approval, 95% power and water coverage, a nonnegative monthly balance and treasury, and 95% storm recovery. The storm arrives in month 30.</p><p>The city loses its commission if the treasury reaches −$5,000 or the deadline passes. After either result, you can continue the city.</p>`,
 growth:`<h3>Read the demand bars</h3><p><strong>R</strong> is residential demand. It rises when jobs and public trust are available. <strong>C</strong> is commercial demand. <strong>I</strong> is industrial demand. Job demand rises with population.</p><p>Empty zones need road access, power, water, and demand. Select a zone with Inspect to see its exact growth blockers.</p><h3>Give each district a role</h3><ul><li>Homes need jobs. Shops and workshops provide them.</li><li>Industry creates pollution. Separate it from homes with distance, trees, or parks.</li><li>Clinics, schools, parks, and fire cover help approval. Coverage changes with service funding.</li><li>At 600 residents, the town receives $3,000 and unlocks dense zones. Dense homes need school coverage for their upper floors.</li><li>At 900 residents and 70% approval, the town receives a further $2,500.</li></ul><h3>Land value affects the city</h3><p>Higher land value gives a small bonus to tax income and growth speed. Parks, services, and waterfront sites raise value. Pollution reduces it.</p><h3>Power shortages are local</h3><p>The utility network supplies civic services first, then zones from north to south. If capacity runs short, affected zones stop growing. Use the network maps to find them.</p>`,
 coast:`<h3>The coast is a design choice</h3><p>Waterfront land has higher value. Low ground near the shore can flood. Open Flood risk to see where the storm can cause damage.</p><table><tbody><tr><td>Flood barrier · $220</td><td>Protects sites within 4 tiles. Place within 4 tiles of the shore.</td></tr><tr><td>Storm shelter · $1,400</td><td>Reduces damage within 8 tiles. Local recovery is twice as fast.</td></tr><tr><td>Raise ground · $160</td><td>Raises vacant land by one level. Height 2+ is safe.</td></tr><tr><td>Repair / respond · $160</td><td>Restores a damaged site at once, or stops an active fire.</td></tr></tbody></table><h3>Read the forecast</h3><p>The council offers a grant in month 12. A storm warning arrives in month 24. You can fund reserve crews, use coastal barriers, build inland, or keep cash for repairs.</p><p>The storm reaches Alder Bay in month 30. Local crews restore damage within six months; shelters can cut that time. Manual repairs are immediate. A fire may occur in an unprotected workshop in month 42.</p>`,
 controls:`<h3>Mouse and touch</h3><table><tbody><tr><td>Left click or tap</td><td>Inspect or place a tool.</td></tr><tr><td>Drag a zone</td><td>Build a rectangular district.</td></tr><tr><td>Drag a road</td><td>Build a road with one turn.</td></tr><tr><td>Right drag / middle drag</td><td>Pan the map.</td></tr><tr><td>Pan hand button</td><td>Use a left drag or one finger to pan.</td></tr><tr><td>Mouse wheel / + / −</td><td>Zoom the map.</td></tr><tr><td>Two fingers</td><td>Pinch to zoom and drag to pan.</td></tr></tbody></table><h3>Keyboard</h3><table><tbody><tr><td><kbd>Space</kbd> / <kbd>P</kbd></td><td>Pause or resume city time.</td></tr><tr><td><kbd>W A S D</kbd> / arrows</td><td>Pan the map.</td></tr><tr><td><kbd>Q R H C I</kbd></td><td>Inspect, road, homes, commerce, industry.</td></tr><tr><td><kbd>B</kbd> / <kbd>F</kbd></td><td>Bulldoze / repair and respond.</td></tr><tr><td><kbd>G</kbd></td><td>Show or hide the tile grid.</td></tr><tr><td><kbd>Ctrl Z</kbd></td><td>Undo construction during this month.</td></tr><tr><td><kbd>Esc</kbd></td><td>Close a window or select Inspect.</td></tr></tbody></table>`,
 about:`<h3>An original coastal city builder</h3><p>Breakwater takes inspiration from the indirect zoning, linked services, terrain, and city scenarios of SimCity 2000 for PC. Alder Bay, its buildings, music, events, and simulation rules are original.</p><p>The game uses the supplied my-3D2dge Agent Edition v0.8.1 as its runtime, projection, pixel renderer, input, and audio foundation.</p><h3>Research sources</h3><ul><li><a href="https://www.abandonwaredos.com/docawd.php?idg=630&sf=simcity2000-manual.txt&sg=SimCity+2000&st=manual" target="_blank" rel="noreferrer">SimCity 2000 manual</a></li><li><a href="https://gamefaqs.gamespot.com/pc/198648-simcity-2000/faqs/33520" target="_blank" rel="noreferrer">Benjer's PC Strategy Guide</a></li><li><a href="https://gamefaqs.gamespot.com/pc/198648-simcity-2000/faqs/7283" target="_blank" rel="noreferrer">Andy007's Scenario Guide</a></li><li><a href="https://en.wikibooks.org/wiki/SimCity/SimCity_2000" target="_blank" rel="noreferrer">Wikibooks: SimCity 2000</a></li><li><a href="https://en.wikipedia.org/wiki/SimCity_2000" target="_blank" rel="noreferrer">Wikipedia: SimCity 2000</a></li></ul><h3>Your city stays on this device</h3><p>The game has no account or cloud save system. It saves to this browser each month. Use Export save in the menu to keep a file or move your city.</p><p>Version 1.0 · One authored scenario · All gameplay runs in your browser.</p>`
};
function help(tab='basics'){guideTab=tab;modal(heading('THE MAYOR’S FIELD GUIDE','A city, one decision at a time'),`<nav class="guide-tabs" aria-label="Field guide sections">${Object.entries({basics:'Start here',growth:'Growth',coast:'The coast',controls:'Controls',about:'About'}).map(([key,label])=>`<button data-guide="${key}" class="${key===tab?'selected':''}">${label}</button>`).join('')}</nav><div class="guide-content">${GUIDE[tab]}</div>`, '<button class="button-primary" id="guide-done">Return to city</button>','help');all('[data-guide]').forEach(b=>b.onclick=()=>help(b.dataset.guide));$('guide-done').onclick=closeModal;}
function bulletin(){modal(heading('THE ALDER BAY BULLETIN','Notes from the coast'),city.events.map(e=>`<article class="bulletin-entry ${e.kind}"><small>${date(e.month)}</small><h3>${esc(e.title)}</h3><p>${esc(e.text)}</p></article>`).join(''),'<button class="button-primary" id="bulletin-done">Return to city</button>','bulletin');$('bulletin-done').onclick=closeModal;}
function showEvent(){
 const event=city.pendingEvent;
 if(event==='grant'){
  modal(heading('COUNCIL DECISION · '+date(city.month),'A grant for Alder Bay','The region will back one plan. Choose the support that fits your city.'),`<button class="event-choice" data-choice="growth"><strong>Put growth first · $3,000</strong><small>Receive $3,000 for roads, zones, and services. Keep control of your own storm preparations.</small></button><button class="event-choice" data-choice="coast"><strong>Prepare the coast · $2,000 + regional crew</strong><small>Receive $2,000 now. A regional crew will protect three exposed sites during the storm.</small></button>`,'','event',false);
 }else if(event==='forecast'){
  modal(heading('COASTAL WEATHER SERVICE · '+date(city.month),'Six months to the squall','A major coastal storm is expected in month 30. Low ground near the shore is exposed.'),`<div class="event-warning">Build barriers near the coast. Add shelters. Raise vacant land to height 2, or build new districts inland.</div><button class="event-choice" data-choice="crews" ${city.funds<1000?'disabled':''}><strong>Call reserve crews · $1,000</strong><small>The reserve crew will protect four exposed sites. You can also build barriers and shelters.</small></button><button class="event-choice" data-choice="prepare"><strong>Use the city’s own plan</strong><small>Keep the funds for construction and recovery. Inspect flood risk before time resumes.</small></button><p id="event-error" class="modal-inline-error hidden"></p>`,'','event',false);
 }else if(event==='storm'){
  renderer.weather=24;
  modal(heading('THE COASTAL SQUALL','The storm has passed',city.stormDamage?`${city.stormDamage} sites were damaged. ${city.stormProtected} sites were protected by coastal works or crews.`:'Alder Bay held. Every occupied site is intact.'),`<div class="intro-illustration"><div class="intro-metric"><small>DAMAGED SITES</small><strong>${city.stormDamage}</strong></div><div class="intro-metric"><small>PROTECTED SITES</small><strong>${city.stormProtected}</strong></div><div class="intro-metric"><small>REPAIR COST</small><strong>${money(city.stormDamage*160)}</strong></div></div><div class="intro-text"><p>Use Repair / respond to restore a site for $160. Local crews also restore damage over time. Shelters reduce the wait.</p><p>The charter requires at least 95% of developed zones and public service sites to be intact.</p></div>`,`<button class="button-primary" data-choice="recover">Return to the city</button>`,'event',false);
 }else return;
 all('[data-choice]').forEach(b=>b.onclick=()=>{const answer=b.dataset.choice,result=city.resolveEvent(answer);if(!result.ok){if($('event-error')){$('event-error').textContent=result.reason;$('event-error').classList.remove('hidden');}else notify(result.reason,true);return;}undoStack=[];closeModal();if(event==='forecast'){setLayer('risk');setSpeed(0);}if(event==='storm'){chooseTool('repair');setSpeed(0);renderer.weather=24;sfx('whoosh');}updateUI();storeSave(true);});
}
function resultModal(){
 const win=city.result==='won';setSpeed(0);tutorial=-1;renderTutorial();
 modal(heading(win?'CHARTER GRANTED · '+date(city.month):'CHARTER REVIEW · '+date(city.month),win?'Alder Bay is a city.':'A new plan is needed.',win?'You built a city with enough homes, public trust, services, and financial strength to meet the coast.':city.funds<=-5000?'The treasury reached the debt limit. The city needs a slower expansion and a stronger tax base.':'The five-year term ended before all charter goals were held for three months.'),
 `<div class="intro-illustration"><div class="intro-metric"><small>RESIDENTS</small><strong>${city.stats.population.toLocaleString()}</strong></div><div class="intro-metric"><small>APPROVAL</small><strong>${city.stats.approval}%</strong></div><div class="intro-metric"><small>MONTHLY BALANCE</small><strong>${signed(city.stats.net)}</strong></div></div><div class="result-goals">${city.goals().map(g=>`<div class="result-goal"><span>${g.label}</span><span>${g.done?'Complete':'Not met'}</span></div>`).join('')}</div><p class="result-note">${win?'Your charter is complete. Keep building Alder Bay, or begin a new term.':'Your city is still here. Continue without the deadline, or start a new term with what you learned.'}</p>`,
 '<button class="button-secondary" id="result-restart">Start a new term</button><button class="button-primary" id="continue-city">Continue city</button>','result',false);
 $('continue-city').onclick=()=>{city.sandbox=true;closeModal();setSpeed(1);updateUI();storeSave(true);};$('result-restart').onclick=()=>confirmRestart();if(win)sfx('powerup');else sfx('pause');
}
function exportSave(){const a=document.createElement('a'),blob=new Blob([JSON.stringify(city.snapshot(),null,2)],{type:'application/json'});a.href=URL.createObjectURL(blob);a.download='alder-bay-'+date(city.month).toLowerCase().replace(' ','-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000);notify('City save exported.');}
function confirmRestart(){modal(heading('START A NEW TERM','Begin again in Alder Bay?','The current city will be replaced. Export a save first if you want to keep it.'),'', '<button class="button-secondary" id="restart-back">Keep this city</button><button class="button-danger" id="restart-confirm">Start a new term</button>','restart');$('restart-back').onclick=closeModal;$('restart-confirm').onclick=()=>{replaceCity(new City());tutorial=0;started=true;closeModal();renderTutorial();storeSave(true);};}
function menu(){
 modal(heading('BREAKWATER','Your city, your pace'),`<div class="menu-grid"><button id="menu-save">${icon('save')} Save city</button><button id="menu-export">${icon('download')} Export save</button><button id="menu-import">${icon('upload')} Import save</button><button id="menu-undo" ${!undoStack.length?'disabled':''}>${icon('undo')} Undo construction</button><button id="menu-records">${icon('chart')} City records</button><button id="menu-restart">${icon('restart')} Start a new term</button></div><p class="menu-status">${esc(saveStatus)}</p><label class="settings-row"><span>Sound & music<small>Original procedural music and city sounds.</small></span><input id="sound-setting" type="checkbox" ${audioOn?'checked':''}></label><label class="settings-row"><span>City animation<small>Moving water, vehicles, trees, and weather effects.</small></span><input id="motion-setting" type="checkbox" ${renderer.animate?'checked':''}></label><label class="settings-row"><span>Simple scenery<small>Reduces tree detail and smoke.</small></span><input id="detail-setting" type="checkbox" ${renderer.lowDetail?'checked':''}></label>`,
 '<button class="button-secondary" id="menu-guide">Field guide</button><button class="button-primary" id="menu-return">Return to city</button>','menu');
 $('menu-save').onclick=()=>{storeSave();menu();};$('menu-export').onclick=exportSave;$('menu-import').onclick=()=>$('import-file').click();$('menu-undo').onclick=()=>{undo();closeModal();};$('menu-records').onclick=recordsModal;$('menu-restart').onclick=confirmRestart;$('menu-guide').onclick=()=>help();$('menu-return').onclick=closeModal;
 $('sound-setting').onchange=toggleAudio;$('motion-setting').onchange=e=>{renderer.animate=e.target.checked;try{localStorage.setItem('breakwater.motion',String(renderer.animate));}catch(err){}};$('detail-setting').onchange=e=>renderer.lowDetail=e.target.checked;
}
let importCandidate=null;
$('import-file').onchange=async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;try{if(f.size>2000000)throw new Error('This save is too large. Select a Breakwater JSON save under 2 MB.');importCandidate=City.fromSave(JSON.parse(await f.text()));modal(heading('IMPORT A CITY','Load this Alder Bay save?',`${date(importCandidate.month)} · ${importCandidate.stats.population.toLocaleString()} residents · ${money(importCandidate.funds)}`),'<p class="intro-text">This will replace the current city on this device.</p>','<button class="button-secondary" id="import-cancel">Cancel</button><button class="button-primary" id="import-confirm">Load city</button>','import');$('import-cancel').onclick=()=>{importCandidate=null;menu();};$('import-confirm').onclick=()=>{replaceCity(importCandidate);importCandidate=null;started=true;tutorial=-1;renderTutorial();closeModal();storeSave(true);notify('City loaded. Time is paused.');if(city.pendingEvent)showEvent();else if(city.result&&!city.sandbox)resultModal();};}catch(err){notify('Cannot load save: '+err.message,true);}};
// Pointer tools. Build actions commit once, when the pointer is released.
const canvas=$('screen');let drag=null,pointers=new Map(),pinch=null;
function cellsBetween(a,b,kind){if(!a||!b)return [];if(kind==='road'){const cells=[];let x=a.x,y=a.y;cells.push({x,y});while(x!==b.x){x+=Math.sign(b.x-x);cells.push({x,y});}while(y!==b.y){y+=Math.sign(b.y-y);cells.push({x,y});}return cells;}
 if(ZONES.includes(kind)||['bulldoze','trees','levee','repair'].includes(kind)){const out=[];for(let y=Math.min(a.y,b.y);y<=Math.max(a.y,b.y);y++)for(let x=Math.min(a.x,b.x);x<=Math.max(a.x,b.x);x++)out.push({x,y});return out;}
 return [{x:b.x,y:b.y}];}
function previewCost(cells){let cost=0,count=0;for(const t of cells){const c=city.canBuild(tool,t.x,t.y,density);if(c.ok){cost+=c.cost;count++;}}return {cost,count};}
function panPixels(dx,dy){const scale=game.screen.dpr/game.screen.S,v=game.view.toGround(-dx*scale,-dy*scale);if(v){camera.x=clamp(camera.x+v[0],-100,N*T+160);camera.y=clamp(camera.y+v[1],-100,N*T+160);}}
canvas.addEventListener('pointerdown',e=>{
 if(!started||$('modal').open)return;canvas.focus({preventScroll:true});pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});canvas.setPointerCapture(e.pointerId);
 if(pointers.size===2){const p=[...pointers.values()];pinch={dist:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),zoom:game.zoom,x:(p[0].x+p[1].x)/2,y:(p[0].y+p[1].y)/2};drag=null;renderer.preview=[];return;}
 const t=renderer.pick(e.clientX,e.clientY);drag={id:e.pointerId,start:t,current:t,x:e.clientX,y:e.clientY,pan:panMode||e.button===1||e.button===2,moved:false,tool};if(!drag.pan&&tool!=='inspect'&&t)renderer.preview=[{x:t.x,y:t.y}];
});
canvas.addEventListener('pointermove',e=>{
 if(!started||$('modal').open)return;
 if(pointers.has(e.pointerId))pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
 if(pointers.size>=2&&pinch){const p=[...pointers.values()],d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),x=(p[0].x+p[1].x)/2,y=(p[0].y+p[1].y)/2;game.setZoom(pinch.zoom*d/Math.max(1,pinch.dist));panPixels(x-pinch.x,y-pinch.y);pinch.x=x;pinch.y=y;updateZoom();return;}
 const t=renderer.pick(e.clientX,e.clientY);renderer.hover=t;const c=t?city.canBuild(tool,t.x,t.y,density):{ok:false};renderer.validPreview=c.ok;
 if(drag&&drag.id===e.pointerId){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>2)drag.moved=true;if(drag.pan){panPixels(dx,dy);$('hover-label').classList.add('hidden');}else if(t&&tool!=='inspect'){drag.current=t;renderer.preview=cellsBetween(drag.start,t,tool);const v=previewCost(renderer.preview);renderer.validPreview=v.count>0&&v.cost<=city.funds;showHover(e,`${v.count} ${v.count===1?'tile':'tiles'} · ${money(v.cost)}`,v.count?'Release to build.':'No valid placement.');}drag.x=e.clientX;drag.y=e.clientY;return;}
 if(t&&!panMode){const desc=tool==='inspect'?(t.type?`Height ${Math.max(0,t.h)} · ${t.access?'Road connected':'No road access'}`:`Height ${Math.max(0,t.h)} · ${t.risk?'Flood exposure':'Safe ground'}`):c.ok?money(c.cost)+' · '+(ZONES.includes(tool)?'Drag to zone.':'Click to build.'):c.reason;showHover(e,tool==='inspect'?currentName(t):BUILD[tool].name,desc);}else $('hover-label').classList.add('hidden');
});
function showHover(e,title,detail){const box=$('hover-label');box.innerHTML=`${esc(title)}<small>${esc(detail||'')}</small>`;box.classList.remove('hidden');const b=canvas.getBoundingClientRect();box.style.left=clamp(e.clientX-b.left+17,5,Math.max(5,b.width-270))+'px';box.style.top=clamp(e.clientY-b.top+20,5,Math.max(5,b.height-65))+'px';}
function endPointer(e,cancel=false){
 pointers.delete(e.pointerId);if(pinch){if(pointers.size<2)pinch=null;drag=null;renderer.preview=[];return;}
 if(!drag||drag.id!==e.pointerId)return;const d=drag;drag=null;renderer.preview=[];
 if(cancel||d.pan||$('modal').open)return;const t=renderer.pick(e.clientX,e.clientY)||d.current;if(!t)return;
 if(tool==='inspect'){selected=t;renderer.selected=t;inspector(t);sfx('blip');return;}
 const cells=cellsBetween(d.start,t,tool);if(!cells.length)return;pushUndo();const result=city.buildMany(tool,cells,density);
 if(!result.ok){undoStack.pop();notify(result.reason||'No valid placement.',true);sfx('bump');}
 else{notify(`${result.count} ${result.count===1?'tile':'tiles'} ${tool==='bulldoze'?'cleared':tool==='repair'?'restored':'built'} · ${money(result.cost)}`);sfx(tool==='bulldoze'?'door':tool==='repair'?'heal':'confirm');if(renderer.animate){for(const t2 of cells.slice(0,20)){const b=city.tile(t2.x,t2.y);game.particles.dust(b.x*T+8,b.y*T+8,renderer.groundZ(b)+2,3,{color:'#c6cbab'});}}}
 updateUI();
}
canvas.addEventListener('pointerup',e=>endPointer(e));canvas.addEventListener('pointercancel',e=>endPointer(e,true));canvas.addEventListener('lostpointercapture',e=>{if(drag?.id===e.pointerId){drag=null;renderer.preview=[];}pointers.delete(e.pointerId);});canvas.addEventListener('pointerleave',()=>{if(!drag){renderer.hover=null;$('hover-label').classList.add('hidden');}});
canvas.addEventListener('wheel',e=>{e.preventDefault();if(!$('modal').open)zoom(e.deltaY<0?1.1:1/1.1);},{passive:false});
window.addEventListener('keydown',e=>{
 if(['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement?.tagName)&&e.code!=='Escape')return;
 if((e.ctrlKey||e.metaKey)&&e.code==='KeyZ'&&!$('modal').open){e.preventDefault();undo();return;}
 if($('modal').open)return;if(!started)return;
 const keys={KeyQ:'inspect',KeyR:'road',KeyH:'home',KeyC:'shop',KeyI:'industry',KeyB:'bulldoze',KeyF:'repair'};
 if(keys[e.code]){e.preventDefault();chooseTool(keys[e.code]);}
 if(e.code==='KeyG'){e.preventDefault();renderer.grid=!renderer.grid;$('grid-button').setAttribute('aria-pressed',String(renderer.grid));}
 if(e.code==='Escape'){chooseTool('inspect');selected=null;renderer.selected=null;inspector(null);}
});
$('modal').addEventListener('cancel',e=>{if(['welcome','event','result'].includes(modalKind)){e.preventDefault();return;}e.preventDefault();closeModal();});
all('[data-tool]').forEach(b=>b.onclick=()=>chooseTool(b.dataset.tool));all('[data-category]').forEach(b=>b.onclick=()=>palette(b.dataset.category));all('[data-density]').forEach(b=>b.onclick=()=>chooseDensity(Number(b.dataset.density)));all('[data-speed]').forEach(b=>b.onclick=()=>setSpeed(Number(b.dataset.speed)));
$('pause-button').onclick=()=>setSpeed(speed?0:lastSpeed);$('sound-button').onclick=toggleAudio;$('help-button').onclick=()=>help();$('menu-button').onclick=menu;$('home-button').onclick=menu;$('budget-button').onclick=budgetModal;$('population-button').onclick=recordsModal;$('approval-button').onclick=recordsModal;$('demand-button').onclick=()=>help('growth');$('bulletin-button').onclick=bulletin;$('storm-button').onclick=()=>{setLayer('risk');if(city.month>=24&&!city.stormDone)notify('The storm arrives in '+(STORM_MONTH-city.month)+' months.');};
$('zoom-in').onclick=()=>zoom(1.15);$('zoom-out').onclick=()=>zoom(1/1.15);$('zoom-label').onclick=fitMap;$('grid-button').onclick=()=>{renderer.grid=!renderer.grid;$('grid-button').setAttribute('aria-pressed',String(renderer.grid));};$('pan-button').onclick=()=>{panMode=!panMode;$('pan-button').setAttribute('aria-pressed',String(panMode));document.body.classList.toggle('pan-cursor',panMode);};$('layer-select').onchange=e=>setLayer(e.target.value);
$('advisor-action').onclick=()=>{if(lastAdvisorAction==='budget')budgetModal();else if(lastAdvisorAction==='records')recordsModal();else if(lastAdvisorAction==='risk')setLayer('risk');else chooseTool(lastAdvisorAction);};
let charterCollapsed=false;$('charter-toggle').onclick=()=>{charterCollapsed=!charterCollapsed;$('charter-content').classList.toggle('hidden',charterCollapsed);$('charter-toggle').innerHTML=icon(charterCollapsed?'plus':'minus');$('charter-toggle').setAttribute('aria-label',charterCollapsed?'Expand charter':'Collapse charter');};
window.addEventListener('beforeunload',()=>{if(started)storeSave(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden&&started){storeSave(true);setSpeed(0);}});
let uiElapsed=0;
game.start({
 update(dt){
  if(started&&!$('modal').open){
   if(game.input.pressed('pause'))setSpeed(speed?0:lastSpeed);if(game.input.pressed('zoomIn'))zoom(1.15);if(game.input.pressed('zoomOut'))zoom(1/1.15);
   const m=game.input.move();if(m[0]||m[1]){const v=game.view.screenDirToGround(...m);camera.x=clamp(camera.x+v[0]*170*dt/game.zoom,-100,N*T+160);camera.y=clamp(camera.y+v[1]*170*dt/game.zoom,-100,N*T+160);}
   if(speed&&(!city.result||city.sandbox)&&!city.pendingEvent){monthTime+=dt*speed;while(monthTime>=8){monthTime-=8;undoStack=[];const beforeEvents=city.events.length;city.tick();updateUI();if(city.events.length>beforeEvents){sfx(city.events[0].kind==='warning'?'blip':'coin');}storeSave(true);if(city.pendingEvent){showEvent();break;}if(city.result&&!city.sandbox){resultModal();break;}}}
  }
  game.focus(camera.x,camera.y,0);renderer.update(dt);uiElapsed+=dt;if(uiElapsed>.8){uiElapsed=0;if(started&&$('modal').open&&modalKind==='menu'){} }
 },
 draw(r){renderer.draw(r);}
});
